import fixtureJson from '../../oracles/fixtures/statistics-rate-smoothing.json';
import {decodeOracleFixture} from '../../oracles/oracle-fixture';

/**
 * Low-dispersion count data (a common underlying rate), so the estimated prior variance is
 * negative. Generated by `test/oracles/statistics-rate-smoothing.py` with esda / numpy:
 * - `unclamped`: esda `Empirical_Bayes(e, b).r` (does not clamp `a`; row 0 is negative).
 * - `clamped`: Marshall (1991) / GeoDa, `a = max(a, 0)` in `w = a / (a + m / b)`, computed in numpy.
 */
export type EBLowDispersionReference = {
  events: number[];
  populations: number[];
  priorVariance: number;
  pooledRate: number;
  unclamped: number[];
  clamped: number[];
};

/** esda `Spatial_Empirical_Bayes` on a 6x6 queen lattice (it clamps `r_var < 0` itself). */
export type SpatialEBLowDispersionReference = {
  events: number[];
  populations: number[];
  offsets: number[];
  neighbors: number[];
  smoothed: number[];
};

const fixture = decodeOracleFixture<{
  generator: string;
  versions: Record<string, string>;
  tolerances: Record<string, unknown>;
  reference: {
    lowDispersion: EBLowDispersionReference;
    spatialLowDispersion: SpatialEBLowDispersionReference;
  };
}>(fixtureJson);

export const EB_LOW_DISPERSION = fixture.reference.lowDispersion;

export const ESDA_SPATIAL_EB_LOW_DISPERSION = fixture.reference.spatialLowDispersion;
